FROM sponsors sp LEFT JOIN spots s ON s.sponsor_id = sp.sponsor_id LEFT JOIN t ON t.episode_id = s.episode_id GROUP BY sp.sponsor_id ORDER BY revenue_eur DESC, sp.name;

